/**
 * `blocks.soundSetEvents` of 26.4 (ADR 0105 D1, D5; plugin API 1.19.0): each vanilla
 * `block_sound_set` entry's sound events, volume and pitch, read from the data files
 * `data/minecraft/block_sound_set/*.json` of the Loom-cached 26.4-snapshot-7 client jar
 * (2026-11-22; sound event ids and two numbers per set, no asset). Checked against the jar by
 * `all/test/block-facts.test.ts` when it is present. An event a set leaves out is silent in
 * vanilla too; volume and pitch default to 1 as the format says.
 */
import type { SoundSetFacts } from '@msm/plugin-api';

/** A set whose five events are all `minecraft:block.<name>.<event>`, at volume and pitch 1. */
const own = (name: string): SoundSetFacts => {
  const id = (event: string): string => `minecraft:block.${name}.${event}`;
  return {
    break: id('break'),
    step: id('step'),
    place: id('place'),
    hit: id('hit'),
    fall: id('fall'),
    volume: 1,
    pitch: 1,
  };
};

