/** Every set by its bare name, sorted. */
export const soundSetEvents: Readonly<Record<string, SoundSetFacts>> = Object.fromEntries(
  [...OWN_SETS.map((name) => [name, own(name)] as const), ...Object.entries(OTHER_SETS)].sort(
    ([a], [b]) => (a < b ? -1 : 1),
  ),
);
